require "rails_helper"

RSpec.describe "committed_data example mode", committed_data: true do
  # "Also add an after-each step that runs after `DatabaseCleaner.clean` and deletes `invoice_operation_intents` and `invoice_operation_outbox_items` rows."
  it "removes intent and outbox rows another connection committed" do
    count_on_other_connection = lambda do |table|
      Thread.new do
        ActiveRecord::Base.connection_pool.with_connection { |connection| connection.select_value("SELECT count(*) FROM #{table}") }
      end.value
    end
    Thread.new do
      ActiveRecord::Base.connection_pool.with_connection do |connection|
        connection.execute(<<~SQL.squish)
          INSERT INTO invoice_operation_intents (company_id, invoice_id, operation_id, state, generation, created_at)
          VALUES (1, 10, gen_random_uuid(), 'pending', 1, now())
        SQL
        connection.execute(<<~SQL.squish)
          INSERT INTO invoice_operation_outbox_items (company_id, invoice_id, operation_id, kind, payload, created_at)
          VALUES (1, 10, gen_random_uuid(), 'commit', '{}'::jsonb, now())
        SQL
      end
    end.join
    expect(count_on_other_connection.call("invoice_operation_intents")).to eq(1)

    TestDatabaseCleanup.delete_operation_ledger_rows!

    expect(count_on_other_connection.call("invoice_operation_intents")).to eq(0)
    expect(count_on_other_connection.call("invoice_operation_outbox_items")).to eq(0)
  end
end

require "rails_helper"

RSpec.describe "Committed-data test mode", committed_data: true do
  # Deletion empties timekeeping_ownership, so the cleanup must put its one row
  # back; TimekeepingOwnership.current raises when the row is missing.
  it "leaves exactly one ownership row after deleting committed test data" do
    InvoiceOperationIntent.create!(company_id: 1, invoice_id: 10, operation_id: SecureRandom.uuid,
                                   state: "pending", generation: 1)

    TestDatabaseCleanup.delete_all_committed!

    expect(TimekeepingOwnership.count).to eq(1)
    expect(TimekeepingOwnership.current).to be_present
    expect(InvoiceOperationIntent.count).to eq(0)
  end
end

